import clsx from 'clsx';
import { ChangeEvent, useState, KeyboardEvent } from 'react';
import { Fragment } from 'react/jsx-runtime';
import { SubmitHandler, useForm } from 'react-hook-form';
import { useLocation } from 'react-router-dom';
import { useSetOnBack } from '~/widgets/sub-layout/use-sub-layout';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { MAX_ATTEMPT_NUMBER } from '~/entities/wallet/model/constants';
import { WalletType } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { overlay } from '~/shared/lib/overlay';
import { PATHS } from '~/shared/routes/paths';
import { Dialog } from '~/shared/ui/dialogs/dialog';

type Inputs = {
  authCode1: string;
  authCode2: string;
  authCode3: string;
};

type InputNames = keyof Inputs;

export type AuthBankAccountParams = {
  walletType: WalletType;
  bankCode: string;
  bankAccount: string;
  auth: string;
};

export const AuthBankAccountPage = () => {
  const [attemptNumber, setAttemptNumber] = useState(0);
  const { navigate, navigateBack } = useNavigate();
  const location = useLocation();
  const state = location?.state as AuthBankAccountParams;

  if (!state?.bankCode || !state?.bankAccount) {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog
          afterLeave={unmount}
          open={isOpen}
          onClose={close}
          message={i18n.t('validation:accountInfoInvalid')}
          onConfirmClick={navigateBack}
        />
      );
    });
  }

  const authText = state?.auth.substring(0, 3);
  const authNumber = state?.auth.substring(3);

  const { bankName } = useComBankInfo(state?.bankCode);
  const {
    register,
    handleSubmit,
    formState: { errors, isValid },
    setError,
    setFocus,
    setValue,
  } = useForm<Inputs>();

  const onSubmit: SubmitHandler<Inputs> = (data) => {
    if (attemptNumber + 1 === MAX_ATTEMPT_NUMBER) {
      overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
        return (
          <Dialog
            afterLeave={unmount}
            open={isOpen}
            onClose={close}
            message={i18n.t('validation:accountAuthAttemptExceeded')}
            onConfirmClick={navigateBack}
          />
        );
      });
      return;
    }

    if (data.authCode1 + data.authCode2 + data.authCode3 !== authNumber) {
      overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
        return (
          <Dialog
            afterLeave={unmount}
            open={isOpen}
            message={i18n.t('validation:accountInfoCheckError')}
            onClose={close}
            onConfirmClick={() => {
              setError('root', { type: 'manual' });
              setAttemptNumber((prev) => prev + 1);
            }}
          />
        );
      });
      return;
    }
    switch (state?.walletType) {
      case WalletType.사업자:
        navigate(PATHS.issueWallet.captureBusinessLicense, { replace: true });
        break;
      case WalletType.개인:
      default:
        navigate(PATHS.issueWallet.chooseIDCardType, { replace: true });
        break;
    }
  };

  const handleChangeAccount = () => {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog
          afterLeave={unmount}
          open={isOpen}
          onClose={close}
          message={i18n.t('text:linkedAccountChangeConfirmation')}
          onConfirmClick={navigateBack}
          buttonLabel={[i18n.t('cancel'), i18n.t('change')]}
        />
      );
    });
  };

  const limitInput = (e: ChangeEvent<HTMLInputElement>) => {
    const tag = e.target as HTMLInputElement;
    setValue(tag.name as InputNames, e.target.value.substring(0, 1));
  };

  const handleInputChange = (e: ChangeEvent<HTMLInputElement>, target: InputNames) => {
    if (e.target.value.length >= 1) {
      limitInput(e);
      setFocus(target);
    }
  };

  const handleInputDelete = (e: KeyboardEvent<HTMLInputElement>, target: InputNames) => {
    if (e.key === 'Backspace' || e.key === 'Delete') {
      const tag = e.target as HTMLInputElement;
      setValue(tag.name as InputNames, '');
      setTimeout(() => {
        setFocus(target);
      }, 100);
      return false;
    }
  };

  const hideKeyboard = (e: ChangeEvent<HTMLInputElement>) => {
    if (e.target.value.length >= 1) {
      limitInput(e);
      e.target.blur();
    }
  };

  useSetOnBack(() =>
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog
          afterLeave={unmount}
          open={isOpen}
          onClose={close}
          onConfirmClick={navigateBack}
          buttonLabel={[i18n.t('cancel'), i18n.t('goBack')]}
          title={i18n.t('validation:returnToBeginning')}
          message={i18n.t('validation:accountInfoResetWarning')}
        />
      );
    }),
  );

  return (
    <Fragment>
      <div className="content sub has-btm-btn">
        <div className="sub-step">
          <span className="on">1step</span>
          <span>2step</span>
          <span>2step</span>
        </div>
        <div className="sub-desc">
          <div
            dangerouslySetInnerHTML={{
              __html: i18n.t('text:oneWonDepositVerification'),
            }}
          />
        </div>

        <form onSubmit={handleSubmit(onSubmit)} className="account-auth-area">
          {authText.split('').map((v: string) => (
            <span key={v} className="auth-text">
              {v}
            </span>
          ))}

          <input
            type="number"
            className="auth-num"
            inputMode="numeric"
            {...register('authCode1', {
              required: true,
              pattern: /[0-9]*/,
              maxLength: 1,
              minLength: 1,
            })}
            onChange={(e) => handleInputChange(e, 'authCode2')}
          />
          <input
            type="number"
            className="auth-num"
            inputMode="numeric"
            {...register('authCode2', {
              required: true,
              pattern: /[0-9]*/,
              maxLength: 1,
              minLength: 1,
            })}
            onChange={(e) => handleInputChange(e, 'authCode3')}
            onKeyDown={(e) => {
              handleInputDelete(e, 'authCode1');
            }}
          />
          <input
            type="number"
            className="auth-num"
            inputMode="numeric"
            {...register('authCode3', {
              required: true,
              pattern: /[0-9]*/,
              maxLength: 1,
              minLength: 1,
            })}
            onChange={(e) => hideKeyboard(e)}
            onKeyDown={(e) => {
              handleInputDelete(e, 'authCode2');
            }}
          />
        </form>

        {errors.root && (
          <div className="ipt-desc-out on text-center">
            {i18n.t('validation:invalidAuthInfo')}
            <span>({attemptNumber}/5)</span>
          </div>
        )}

        <div className="account-info-area">
          <div className="account-info">
            <p>
              {bankName} {state?.bankAccount}
            </p>
            <button type="button" className="account-btn" onClick={handleChangeAccount}>
              {i18n.t('changeAccount')}
            </button>
          </div>
        </div>
      </div>
      <div className="btm-btn-area">
        <button
          type="button"
          className={clsx('btm-btn app', { disabled: !isValid })}
          disabled={!isValid}
          onClick={handleSubmit(onSubmit)}
        >
          {i18n.t('oneWonVerification')}
        </button>
      </div>
    </Fragment>
  );
};
